INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `short_description`, `description`, `base_price`, `compare_price`, `sku`, `frame_image`, `sample_image`, `min_images`, `max_images`, `allowed_print_types`, `customization_config`, `mask_data`, `meta_title`, `meta_description`, `meta_keywords`, `is_featured`, `is_active`, `sort_order`, `views_count`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, 'Classic Acrylic Wall Photo', 'classic-acrylic-wall-photo', 'Transform your favorite photo into a stunning acrylic wall piece with vivid colors and crystal-clear finish.', 'Our Classic Acrylic Wall Photo is the perfect way to showcase your cherished memories. Printed using state-of-the-art UV technology directly onto premium 3mm acrylic glass, your photos come alive with incredible depth and vibrancy.\r\n\r\n• Crystal-clear 3mm acrylic glass\r\n• UV-direct printing for vivid colors\r\n• Pre-drilled mounting holes included\r\n• Lightweight and durable\r\n• Scratch-resistant coating\r\n• Available in multiple sizes', 1299.00, 1999.00, 'ACP-001', 'products/frames/EGis0PMe5QJGSOULCEOE9mZp23amnKbcAHy3ErO0.png', 'products/samples/IMWkvZbIPCaSxvI7QmLmcRLiayIfKl7OkUZu5m44.jpg', 1, 1, '[\"noritsu\"]', NULL, '{\"frame\":{\"left\":0,\"top\":0,\"scaleX\":0.6,\"scaleY\":0.6004},\"masks\":[{\"type\":\"square\",\"left\":148.53,\"top\":149.04,\"scaleX\":2.9001,\"scaleY\":2.9001,\"angle\":0,\"width\":100,\"height\":100,\"fill\":\"#ff0000\",\"stroke\":\"#7a7a7a\",\"strokeWidth\":2,\"opacity\":1}],\"canvasWidth\":600,\"canvasHeight\":583}', 'Custom Acrylic Wall Photo Print | Premium Quality', 'Create custom acrylic wall art from your photos. Crystal-clear finish, vibrant colors. Free shipping on ₹999+.', NULL, 1, 1, 0, 3, '2026-02-16 09:44:10', '2026-02-20 14:00:36', NULL),
(2, 1, 'Acrylic Photo Collage Board', 'acrylic-photo-collage-board', 'Create a stunning multi-photo collage on premium acrylic. Perfect for gifting or home decor.', 'Combine up to 9 of your favorite photos into one beautiful acrylic art piece. Our collage board features a sleek, modern look that\'s perfect for any room.\r\n\r\n• Up to 9 photos per board\r\n• Professional layout design\r\n• Premium 3mm acrylic\r\n• Ready to hang\r\n• Available in various grid layouts', 1999.00, 2999.00, 'APC-002', 'products/frames/p3Vgla5xwXLRHCe4Qsd43k2i3aRfIcoXuAHBsgDl.png', 'products/samples/Z1rENJJ5j4kKKGZwbESsRJ71pgX3W57UDAayAsdb.webp', 2, 9, '[\"noritsu\",\"standard\"]', NULL, '{\"frame\":{\"left\":0,\"top\":0,\"scaleX\":0.5556,\"scaleY\":0.5556},\"masks\":[{\"type\":\"square\",\"left\":135.53,\"top\":339.8,\"scaleX\":3.0392,\"scaleY\":1.9992,\"angle\":354.82,\"width\":100,\"height\":100,\"fill\":\"rgba(0, 100, 255, 0.45)\",\"stroke\":\"rgba(0, 80, 220, 0.9)\",\"strokeWidth\":2,\"opacity\":1},{\"type\":\"square\",\"left\":119.95,\"top\":91.99,\"scaleX\":1.4814,\"scaleY\":1.7682,\"angle\":355.27,\"width\":100,\"height\":100,\"fill\":\"rgba(0, 100, 255, 0.45)\",\"stroke\":\"rgba(0, 80, 220, 0.9)\",\"strokeWidth\":2,\"opacity\":1},{\"type\":\"square\",\"left\":275.27,\"top\":79.18,\"scaleX\":1.4915,\"scaleY\":1.7939,\"angle\":355.07,\"width\":100,\"height\":100,\"fill\":\"rgba(0, 100, 255, 0.45)\",\"stroke\":\"rgba(0, 80, 220, 0.9)\",\"strokeWidth\":2,\"opacity\":1}],\"canvasWidth\":600,\"canvasHeight\":600}', NULL, NULL, NULL, 1, 1, 0, 2, '2026-02-16 09:44:10', '2026-02-23 11:47:16', NULL),
(3, 2, 'Gallery Canvas Print', 'gallery-canvas-print', 'Museum-quality canvas print stretched on solid wood frame. Rich textures and true-to-life colors.', 'Turn your photos into gallery-worthy art with our premium canvas prints. Each print is made using archival-quality inks on premium cotton-poly blend canvas, stretched over a 1.5\" solid wood frame.\r\n\r\n• Premium cotton-poly canvas\r\n• Archival-quality inks\r\n• 1.5\" solid wood stretcher bars\r\n• Mirror-wrapped edges\r\n• Ready to hang hardware included', 999.00, 1499.00, 'CNV-001', 'products/frames/1TI2d8IxC3PQG6JXJQ0jqxZNGjVxMT58RN1BLCKn.jpg', 'products/samples/udbyFqR0IabfoQQXmHwqlm99dYM2yLdFbJ7QCVFL.jpg', 1, 6, '[\"noritsu\"]', NULL, '{\"frame\":{\"left\":0,\"top\":0,\"scaleX\":0.9804,\"scaleY\":0.9809},\"masks\":[{\"type\":\"square\",\"left\":231.97,\"top\":25.16,\"scaleX\":1.3182,\"scaleY\":1.9604,\"angle\":0,\"width\":100,\"height\":100,\"fill\":\"rgba(0, 100, 255, 0.45)\",\"stroke\":\"rgba(0, 80, 220, 0.9)\",\"strokeWidth\":2,\"opacity\":1},{\"type\":\"square\",\"left\":421.01,\"top\":64.05,\"scaleX\":1.4642,\"scaleY\":1.4642,\"angle\":0,\"width\":100,\"height\":100,\"fill\":\"rgba(0, 100, 255, 0.45)\",\"stroke\":\"rgba(0, 80, 220, 0.9)\",\"strokeWidth\":2,\"opacity\":1},{\"type\":\"oval\",\"left\":53.76,\"top\":16.46,\"scaleX\":1.052,\"scaleY\":1.052,\"angle\":0,\"width\":100,\"height\":140,\"rx\":50,\"ry\":70,\"fill\":\"rgba(0, 100, 255, 0.45)\",\"stroke\":\"rgba(0, 80, 220, 0.9)\",\"strokeWidth\":2,\"opacity\":1}],\"canvasWidth\":600,\"canvasHeight\":257}', NULL, NULL, NULL, 1, 1, 0, 6, '2026-02-16 09:44:10', '2026-02-24 13:04:13', NULL),
(4, 2, 'Split Canvas Set', 'split-canvas-set', 'Your photo split across multiple canvas panels for a dramatic display. A showstopper for any wall.', 'Make a bold statement with our split canvas sets. Your single photo is artfully divided across 3 or 5 panels, creating a stunning panoramic display.\r\n\r\n• Available in 3 or 5 panel sets\r\n• Professional split calculation\r\n• Consistent color across panels\r\n• Premium canvas material\r\n• Easy installation guide included', 2499.00, 3499.00, 'CNV-002', 'products/frames/J3FThYRSHxca68qddpVcSGfdaByNNGElLEK2GHKV.png', 'products/samples/ugt2RbFjU872E8CgNJ8gewkY9Q0gleukAJcu4aiJ.png', 1, 1, '[\"noritsu\"]', NULL, '{\"frame\":{\"left\":0,\"top\":0,\"scaleX\":1,\"scaleY\":1},\"masks\":[{\"type\":\"rectangle\",\"left\":31.02,\"top\":51.21,\"scaleX\":3.5063,\"scaleY\":3.4054,\"angle\":357.36,\"width\":150,\"height\":100,\"fill\":\"rgba(0, 100, 255, 0.45)\",\"stroke\":\"rgba(0, 80, 220, 0.9)\",\"strokeWidth\":2,\"opacity\":1}],\"canvasWidth\":600,\"canvasHeight\":422}', NULL, NULL, NULL, 1, 1, 0, 0, '2026-02-16 09:44:10', '2026-02-24 12:55:16', NULL),
(5, 3, 'Premium Poster Print', 'premium-poster-print', 'Affordable high-quality poster prints on premium matte or glossy paper. Perfect for any space.', 'Get stunning poster prints at affordable prices without compromising on quality. Printed on 300gsm premium paper stock with archival inks.\n\n• 300gsm premium paper\n• Matte or glossy finish\n• Archival quality inks\n• Sharp detail reproduction\n• Rolled in protective tube', 399.00, 599.00, 'PST-001', NULL, NULL, 1, 1, '[\"noritsu\"]', NULL, NULL, NULL, NULL, NULL, 0, 1, 0, 0, '2026-02-16 09:44:10', '2026-02-23 13:07:48', NULL),
(6, 4, 'Custom Framed Portrait', 'custom-framed-portrait', 'Beautifully framed photo prints with premium wooden or metal frames. Gallery-ready art for your walls.', 'Elevate your photos with our custom framing service. Choose from premium wood or sleek metal frames, paired with gallery-grade glass for lasting beauty.\n\n• Premium wood or metal frames\n• Museum-grade UV glass\n• Acid-free matting\n• Professional mounting\n• Ready to hang', 1799.00, 2499.00, 'FRM-001', NULL, NULL, 1, 1, '[\"noritsu\"]', NULL, NULL, NULL, NULL, NULL, 0, 1, 0, 0, '2026-02-16 09:44:10', '2026-02-23 13:07:48', NULL),
(7, 5, 'Heart-Shape Photo Collage', 'heart-shape-photo-collage', 'Your favorite photos arranged in a beautiful heart shape. Perfect gift for loved ones.', 'Express your love with our heart-shaped photo collage. Upload 10-30 photos and we\'ll arrange them in a beautiful heart formation.\n\n• Unique heart-shaped layout\n• 10-30 photos per collage\n• Available on acrylic, canvas, or poster\n• Multiple size options\n• Professional photo arrangement', 1499.00, 2199.00, 'CLG-001', NULL, NULL, 10, 30, '[\"noritsu\"]', NULL, NULL, NULL, NULL, NULL, 1, 1, 0, 0, '2026-02-16 09:44:10', '2026-02-23 13:07:48', NULL),
(8, 6, 'Brushed Aluminum Photo', 'brushed-aluminum-photo', 'Modern metal prints with a stunning brushed aluminum finish. Ultra-durable and weatherproof.', 'Give your photos a modern, industrial look with our brushed aluminum prints. Your image is infused directly into the metal for exceptional durability and vivid color.\n\n• Premium brushed aluminum\n• Dye-sublimation printing\n• Weatherproof & UV resistant\n• Float mount included\n• Modern, frameless look', 2299.00, 3299.00, 'MTL-001', NULL, NULL, 1, 1, '[\"noritsu\"]', NULL, NULL, NULL, NULL, NULL, 0, 1, 0, 1, '2026-02-16 09:44:10', '2026-02-23 13:07:48', NULL);

